-- ============================================================
-- PAWS — DATABASE v2  ·  ROBOT SINGLE-ROW + v2.9 SENSOR COLUMNS
-- one paste · safe to re-run · SIH 2026 · PS 26223
-- ============================================================
-- WHY THIS FILE (one paste does everything):
--   1) CLEANUP  : removes the old-test telemetry rows (orphans from
--                 the previous firmware) so the single live row is clean.
--   2) ID FIX   : the v2.9 firmware always sends "id":1 → we accept it
--                 (id becomes GENERATED BY DEFAULT). THIS kills the 400.
--   3) COLUMNS  : the 27 new v2.9 sensor columns (ppm, dB, sonar bins,
--                 laser/imu/thermal/climate/pir words, odometry, …).
--   4) ANON PATH: INSERT+SELECT+UPDATE grant + RLS policy, because
--                 PostgREST's merge-duplicates upsert needs UPDATE,
--                 and its default response reads the row back (SELECT).
--   5) TRIGGER  : rewritten as BEFORE INSERT OR UPDATE → on EVERY upload
--                 (first insert AND every upsert) it fills mission_id /
--                 device_id / robot_id / ts / payload, keeps "one mission
--                 per robot" (auto-creates lazily), and refreshes the
--                 SINGLE mission_state row in place.
--   6) REALTIME : telemetry + mission_state in the publication so the
--                 console is pushed every 2 s.
--
-- ALREADY HAVE OLD ROWS?  Yes — this deletes public.telemetry (old-test
-- rows only). detections (camera log) is NOT touched. Re-running this
-- file later deletes telemetry again → only run the delete until the
-- robot is live; afterwards the triggers/columns above are all no-ops
-- and perfectly safe to re-run.
-- ============================================================

-- ---------- 0. RUN-ONCE CLEANUP (old-test telemetry rows) -----------
delete from public.telemetry;
-- Uncomment only if you ALSO want a clean camera/state history now:
-- delete from public.detections;
-- delete from public.trail_points;
-- delete from public.events;
-- delete from public.mission_state;
-- delete from public.missions;

-- ---------- 1. accept the robot's fixed primary key  ("id":1) -------
alter table public.telemetry alter column id set generated by default;

-- ---------- 2. v2.9 sensor columns (idempotent) --------------------
alter table public.telemetry add column if not exists lpg_ppm          numeric;
alter table public.telemetry add column if not exists smoke_ppm        numeric;
alter table public.telemetry add column if not exists aqi_band         text;
alter table public.telemetry add column if not exists sound_db         numeric;
alter table public.telemetry add column if not exists sound_band       text;
alter table public.telemetry add column if not exists mic_peak_db      numeric;
alter table public.telemetry add column if not exists ultra_front_cm   numeric;
alter table public.telemetry add column if not exists ultra_left_cm    numeric;
alter table public.telemetry add column if not exists ultra_right_cm   numeric;
alter table public.telemetry add column if not exists ultra_state      text;
alter table public.telemetry add column if not exists laser_state      text;
alter table public.telemetry add column if not exists laser_match      text;
alter table public.telemetry add column if not exists imu_pitch_deg    numeric;
alter table public.telemetry add column if not exists imu_roll_deg     numeric;
alter table public.telemetry add column if not exists imu_attitude     text;
alter table public.telemetry add column if not exists thermal_delta_c  numeric;
alter table public.telemetry add column if not exists thermal_zone     text;
alter table public.telemetry add column if not exists humidity_pct     numeric;
alter table public.telemetry add column if not exists humidity_band    text;
alter table public.telemetry add column if not exists pir_state        text;
alter table public.telemetry add column if not exists pir_events_total bigint;
alter table public.telemetry add column if not exists pir_rate_per_min int;
alter table public.telemetry add column if not exists pir_last_trigger_s bigint;
alter table public.telemetry add column if not exists robot_x_cm       bigint;
alter table public.telemetry add column if not exists robot_y_cm       bigint;
alter table public.telemetry add column if not exists robot_heading_deg int;

-- ---------- 3. anon permissions (PostgREST upsert) ------------------
grant usage on schema public to anon;
grant insert, select, update on public.telemetry to anon;

drop policy if exists "telemetry_anon_insert" on public.telemetry;
drop policy if exists "telemetry_anon_upsert" on public.telemetry;
create policy "telemetry_anon_upsert" on public.telemetry
  for all to anon using (true) with check (true);

-- ---------- 4. trigger: enrich every upload + refresh single row ---
create or replace function public.rewrite_device_telemetry()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_robot    text := coalesce(new.device_id, 'paws-01');
  v_mission  text;
  v_ts       bigint;
  v_now_ms   bigint := (extract(epoch from clock_timestamp()) * 1000)::bigint;
  v_sensors  jsonb := '{}'::jsonb;
begin
  -- rows that already carry a full payload (seed/demo writes) skip enrichment
  if tg_op = 'INSERT' and new.payload is not null then
    return new;
  end if;

  begin
    v_ts := (extract(epoch from (new.recorded_at::timestamptz)) * 1000)::bigint;
  exception when others then
    v_ts := v_now_ms;
  end;
  if new.robot_id is not null then
    v_robot := new.robot_id;
  end if;

  -- ONE running mission per robot (auto-created lazily on first upload)
  select id into v_mission from public.missions
  where status = 'running' and robot_id = v_robot
  order by started_at desc limit 1;
  if v_mission is null then
    v_mission := 'mis_' || replace(gen_random_uuid()::text, '-', '');
    insert into public.missions (id, name, status, started_at, origin, robot_id)
    values (v_mission, 'Field Mission — ' || v_robot, 'running', now(),
            jsonb_build_object('xM', 0, 'yM', 0, 'setAt', v_now_ms), v_robot);
  end if;

  insert into public.robots (id, name) values (v_robot, 'PAWS ' || upper(v_robot))
  on conflict (id) do update set last_seen_at = now();

  -- ---- sensor map for the console (same units/words as the OLED) ----
  if new.sound_level is not null then
    v_sensors := v_sensors || jsonb_build_object('sound', jsonb_strip_nulls(jsonb_build_object(
      'amp', round(least(1.0::numeric, greatest(0.0::numeric, new.sound_level / 4095.0)), 4),
      'db', round(new.sound_db, 1), 'band', new.sound_band,
      'peakDb', round(new.mic_peak_db, 1), 'heardAt', v_ts)));
  end if;

  if new.gas_level is not null then
    v_sensors := v_sensors || jsonb_build_object('gas', jsonb_strip_nulls(jsonb_build_object(
      'adc', least(4095, greatest(0, round(new.gas_level)))::int,
      'ppm', round(new.lpg_ppm, 3), 'smoke', round(new.smoke_ppm, 3),
      'aqiBand', new.aqi_band, 'warming', (new.lpg_ppm = -1.0), 'heardAt', v_ts)));
  end if;

  if new.ultra_front_cm is not null or new.distance_cm is not null then
    v_sensors := v_sensors || jsonb_build_object('distance', jsonb_strip_nulls(jsonb_build_object(
      'cm', round(coalesce(nullif(new.ultra_front_cm, -1), nullif(new.distance_cm, -1)), 1),
      'cmLeft', round(nullif(new.ultra_left_cm, -1), 1),
      'cmRight', round(nullif(new.ultra_right_cm, -1), 1),
      'state', new.ultra_state, 'heardAt', v_ts)));
  end if;

  if new.laser_distance_mm is not null or new.laser_state is not null then
    v_sensors := v_sensors || jsonb_build_object('laser', jsonb_strip_nulls(jsonb_build_object(
      'mm', round(nullif(new.laser_distance_mm, -1), 0),
      'state', new.laser_state, 'match', new.laser_match, 'heardAt', v_ts)));
  end if;

  if new.imu_pitch_deg is not null or new.tilt_angle is not null then
    v_sensors := v_sensors || jsonb_build_object('imu', jsonb_strip_nulls(jsonb_build_object(
      'pitchDeg', round(new.imu_pitch_deg, 1), 'rollDeg', round(new.imu_roll_deg, 1),
      'tiltDeg', round(new.tilt_angle, 1), 'attitude', new.imu_attitude,
      'headingDeg', new.robot_heading_deg, 'heardAt', v_ts)));
  end if;

  if new.object_temp_c is not null and new.object_temp_c > -200 then
    v_sensors := v_sensors || jsonb_build_object('thermal', jsonb_strip_nulls(jsonb_build_object(
      'objectC', round(new.object_temp_c, 1), 'ambientC', round(new.ambient_temp_c, 1),
      'deltaC', round(new.thermal_delta_c, 1), 'zone', new.thermal_zone, 'heardAt', v_ts)));
  end if;

  if new.humidity_pct is not null and new.humidity_pct > -100 then
    v_sensors := v_sensors || jsonb_build_object('climate', jsonb_strip_nulls(jsonb_build_object(
      'tempC', round(new.temperature_c, 1), 'humidityPct', round(new.humidity_pct, 1),
      'band', new.humidity_band, 'heardAt', v_ts)));
  end if;

  if new.pir_state is not null then
    v_sensors := v_sensors || jsonb_build_object('pir', jsonb_strip_nulls(jsonb_build_object(
      'state', new.pir_state, 'total', new.pir_events_total,
      'perMin', new.pir_rate_per_min, 'lastSecs', new.pir_last_trigger_s, 'heardAt', v_ts)));
  end if;

  if new.robot_x_cm is not null then
    v_sensors := v_sensors || jsonb_build_object('odom', jsonb_strip_nulls(jsonb_build_object(
      'xCm', new.robot_x_cm, 'yCm', new.robot_y_cm,
      'headingDeg', new.robot_heading_deg, 'heardAt', v_ts)));
  end if;

  new.mission_id := v_mission;
  new.device_id  := v_robot;
  new.robot_id   := v_robot;
  new.ts         := v_ts;
  new.payload    := jsonb_build_object(
      'deviceId', v_robot, 'ts', v_ts, 'seq', (v_ts % 1000000000)::int
    ) || v_sensors;

  -- THE single live mission-state row: updated in place on every upload
  insert into public.mission_state (mission_id, sensors, updated_at)
  values (v_mission, jsonb_strip_nulls(v_sensors), now())
  on conflict (mission_id) do update
    set sensors    = mission_state.sensors || excluded.sensors,
        updated_at = excluded.updated_at;

  return new;
end;
$$;

drop trigger if exists rewrite_device_telemetry on public.telemetry;
create trigger rewrite_device_telemetry
  before insert or update on public.telemetry
  for each row execute function public.rewrite_device_telemetry();

-- ---------- 5. realtime publication (console push) ------------------
do $$
begin
  begin alter publication supabase_realtime add table public.telemetry;
  exception when duplicate_object or undefined_table then null; end;
  begin alter publication supabase_realtime add table public.mission_state;
  exception when duplicate_object or undefined_table then null; end;
  begin alter publication supabase_realtime add table public.events;
  exception when duplicate_object or undefined_table then null; end;
  begin alter publication supabase_realtime add table public.trail_points;
  exception when duplicate_object or undefined_table then null; end;
end $$;

notify pgrst, 'reload schema';

-- ============================================================
-- DONE. Expected behaviour after this paste:
--   1st robot upload  → HTTP 201 (row id=1 created)
--   every next upload → HTTP 204 (row id=1 updated in place)
--   serial shows      → [Supabase] HTTP response code: 201 then 204
--   Table Editor      → telemetry: ONE row (id=1), values changing
--                       every 2 s; mission_state: ONE row updating
--   NOT touched       → detections / camera log keeps appending
-- ============================================================
